+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Anchor;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final MessageStore store;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        setWidthFull();
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        name.setWidthFull();
+        email.setWidthFull();
+        phone.setWidthFull();
+        message.setWidthFull();
+        message.setHeight("140px");
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        send.setEnabled(true);
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+        add(name, email, phone, message, send);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        grid.setItems(store.newestFirst());
+        grid.setWidthFull();
+        add(grid);
+
+        name.addValueChangeListener(event -> edited());
+        email.addValueChangeListener(event -> edited());
+        phone.addValueChangeListener(event -> edited());
+        message.addValueChangeListener(event -> edited());
+    }
+
+    private void edited() {
+        send.setEnabled(true);
+    }
+
+    private void submit() {
+        boolean valid = true;
+        String nameValue = name.getValue() == null ? "" : name.getValue();
+        String emailValue = email.getValue() == null ? "" : email.getValue().trim();
+        String phoneValue = phone.getValue() == null ? "" : phone.getValue().trim();
+        String messageValue = message.getValue() == null ? "" : message.getValue();
+
+        boolean nameInvalid = nameValue.isBlank();
+        name.setInvalid(nameInvalid);
+        name.setErrorMessage(nameInvalid ? "Name is required" : null);
+        valid &= !nameInvalid;
+
+        boolean emailInvalid = !emailValue.isEmpty() && !isValidEmail(emailValue);
+        boolean contactMissing = emailValue.isEmpty() && phoneValue.isEmpty();
+        email.setInvalid(emailInvalid || contactMissing);
+        email.setErrorMessage(emailInvalid ? "Enter a valid e-mail address"
+                : contactMissing ? "Give an e-mail address or a phone number" : null);
+        valid &= !emailInvalid && !contactMissing;
+
+        boolean messageBlank = messageValue.isBlank();
+        boolean messageTooLong = messageValue.length() > 500;
+        message.setInvalid(messageBlank || messageTooLong);
+        message.setErrorMessage(messageBlank ? "Message is required"
+                : messageTooLong ? "Message must be at most 500 characters" : null);
+        valid &= !messageBlank && !messageTooLong;
+
+        if (!valid) return;
+
+        ContactMessage sent = new ContactMessage(nameValue.trim(), emailValue, phoneValue, messageValue);
+        store.add(sent);
+        grid.setItems(store.newestFirst());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing changes values and triggers the edit listeners; success is the sole disabled state.
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValidEmail(String value) {
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasContent()) return;
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add("You have unsent content. Do you want to discard it?");
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+
+    private boolean hasContent() {
+        return nonEmpty(name.getValue()) || nonEmpty(email.getValue())
+                || nonEmpty(phone.getValue()) || nonEmpty(message.getValue());
+    }
+
+    private boolean nonEmpty(String value) {
+        return value != null && !value.isEmpty();
+    }
+}
